def buat_konfigurasi_unit(apps, schema_editor):
    """Satu baris Akun Unit Bisnis + Departemen bernama sama per unit bisnis.
    Akun pengganti dibiarkan kosong: jurnal tetap memakai akun umum sampai
    Owner/Finance mengisinya; yang langsung berlaku hanya tanda departemen."""
    UnitBisnis = apps.get_model('api', 'UnitBisnis')
    Department = apps.get_model('accounting', 'Department')
    AkunUnitBisnis = apps.get_model('accounting', 'AkunUnitBisnis')
    for unit in UnitBisnis.objects.all():
        cfg, _ = AkunUnitBisnis.objects.get_or_create(unit_bisnis=unit)
        if cfg.department_id is None:
            dept, _ = Department.objects.get_or_create(name=unit.nama[:100])
            if not AkunUnitBisnis.objects.filter(department=dept).exists():
                cfg.department = dept
                cfg.save(update_fields=['department'])


